using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;
namespace FreeNormalFinder {
public sealed partial class ToolForm {
    string ManualMemoFilePath(string name){if(String.IsNullOrEmpty(name)||Path.GetFileName(name)!=name||!name.EndsWith(".json",StringComparison.OrdinalIgnoreCase))throw new Exception("メモの保存先が不正です。");return Path.Combine(ManualMemoStorageDirectory,name);}
    ManualMemoDocument ReadManualMemo(string path){
        if(!String.Equals(Path.GetFullPath(Path.GetDirectoryName(path)),Path.GetFullPath(ManualMemoStorageDirectory),StringComparison.OrdinalIgnoreCase))throw new Exception("新規メモ専用の保存ファイルを選択してください。");
        if(new FileInfo(path).Length>64*1024*1024)throw new Exception("メモが大きすぎます。");
        var doc=SavedInputSerializer().Deserialize<ManualMemoDocument>(File.ReadAllText(path,Encoding.UTF8));Guid id;
        if(doc==null||!(doc.Schema=="free-manual-doping-memo-v2"&&doc.Version==2||doc.Schema=="free-manual-doping-memo-v3"&&doc.Version==3||doc.Schema=="free-manual-doping-memo-v4"&&doc.Version==4)||!Guid.TryParseExact(doc.Id,"N",out id)||String.IsNullOrWhiteSpace(doc.Label)||doc.Label.Length>80||doc.Individuals==null||doc.Individuals.Length>256||doc.VisibleGenerations==null||doc.VisibleGenerations.Any(g=>g<1||g>9)||doc.VisibleGenerations.Distinct().Count()!=doc.VisibleGenerations.Length)throw new Exception("新規メモの保存形式ではありません。");
        foreach(var person in doc.Individuals)ValidateManualPerson(person);if(doc.Individuals.Select(p=>p.Id).Distinct().Count()!=doc.Individuals.Length)throw new Exception("個体番号が重複しています。");if(doc.Version>=3)ValidateMemoGraph(doc);return doc;
    }
    void RefreshManualMemoInputs(){changingManualMemoInput=true;try{manualMemoInput.Items.Clear();if(Directory.Exists(ManualMemoStorageDirectory))foreach(var path in Directory.GetFiles(ManualMemoStorageDirectory,"*.json").OrderBy(p=>p)){try{var doc=ReadManualMemo(path);manualMemoInput.Items.Add(new ManualMemoSavedChoice{Id=doc.Id,Label=doc.Label,FileName=Path.GetFileName(path)});}catch{}}}finally{changingManualMemoInput=false;}SelectManualMemoInput();}
    void SelectManualMemoInput(){changingManualMemoInput=true;try{manualMemoInput.SelectedIndex=-1;for(int i=0;i<manualMemoInput.Items.Count;i++)if(manualMemoPath!=null&&String.Equals(ManualMemoFilePath(((ManualMemoSavedChoice)manualMemoInput.Items[i]).FileName),manualMemoPath,StringComparison.OrdinalIgnoreCase)){manualMemoInput.SelectedIndex=i;break;}}finally{changingManualMemoInput=false;}}
    string ManualMemoAutomaticName(){var first=manualMemoPeople.OrderByDescending(p=>p.Generation).FirstOrDefault();return first==null?"ドーピングメモ":ManualPersonName(first);}
    public void LoadManualDopingMemo(string path){path=Path.GetFullPath(path);var doc=ReadManualMemo(path);var info=new FileInfo(path);manualMemoPeople.Clear();manualMemoPeople.AddRange(doc.Individuals.Select(p=>p.Copy()));manualMemoBranches.Clear();manualMemoTreeRoots.Clear();if(doc.Version>=3){manualMemoBranches.AddRange(doc.Branches);manualMemoTreeRoots.AddRange(doc.Roots);}manualMemoPath=path;manualMemoId=doc.Id;manualMemoLabel=doc.Label;manualMemoLength=info.Length;manualMemoWriteTicks=info.LastWriteTimeUtc.Ticks;changingManualMemoGenerations=true;try{for(int g=1;g<=9;g++)manualMemoGenerations[g].Checked=doc.VisibleGenerations.Contains(g);}finally{changingManualMemoGenerations=false;}if(doc.Version==2)ImportLegacyMemoGraph();manualMemoDirty=false;RefreshManualMemoInputs();RenderManualMemo();}
    public string SaveManualDopingMemo(){if(manualMemoPath==null)return SaveManualDopingMemoAs(ManualMemoAutomaticName());var info=new FileInfo(manualMemoPath);if(!info.Exists||info.Length!=manualMemoLength||info.LastWriteTimeUtc.Ticks!=manualMemoWriteTicks)throw new Exception("保存ファイルが外部で変更されています。名前を付けて保存してください。");return WriteManualMemo(manualMemoPath,manualMemoId,manualMemoLabel,false);}
    public string SaveManualDopingMemoAs(string label){
        if(String.IsNullOrWhiteSpace(label)||label.Trim().Length>80)throw new Exception("保存名は1～80文字で入力してください。");label=label.Trim();string safe=String.Concat(label.Select(c=>Path.GetInvalidFileNameChars().Contains(c)?'_':c)).TrimEnd(' ','.');if(safe.Length==0)safe="ドーピングメモ";string stem=safe.Split('.')[0].ToUpperInvariant();if(new[]{"CON","PRN","AUX","NUL","COM1","COM2","COM3","COM4","COM5","COM6","COM7","COM8","COM9","LPT1","LPT2","LPT3","LPT4","LPT5","LPT6","LPT7","LPT8","LPT9"}.Contains(stem))safe="_"+safe;
        Directory.CreateDirectory(ManualMemoStorageDirectory);string path=ManualMemoFilePath(safe+".json"),actual=label;int suffix=2;while(File.Exists(path)){string number=suffix.ToString();actual=label.Substring(0,Math.Min(label.Length,80-number.Length))+number;path=ManualMemoFilePath(safe+number+".json");suffix++;}return WriteManualMemo(path,Guid.NewGuid().ToString("N"),actual,true);
    }
    string WriteManualMemo(string path,string id,string label,bool fresh){EnsureMemoTournament();foreach(var person in manualMemoPeople)ValidateManualPerson(person);var doc=new ManualMemoDocument{Id=id,Label=label,Individuals=ManualMemoIndividuals,VisibleGenerations=Enumerable.Range(1,9).Where(g=>manualMemoGenerations[g].Checked).ToArray(),Branches=manualMemoBranches.ToArray(),Roots=manualMemoTreeRoots.ToArray()};ValidateMemoGraph(doc);string temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(temp,SavedInputSerializer().Serialize(doc),new UTF8Encoding(false));if(fresh)File.Move(temp,path);else File.Replace(temp,path,null);}finally{if(File.Exists(temp))File.Delete(temp);}manualMemoPath=path;manualMemoId=id;manualMemoLabel=label;var info=new FileInfo(path);manualMemoLength=info.Length;manualMemoWriteTicks=info.LastWriteTimeUtc.Ticks;manualMemoDirty=false;RefreshManualMemoInputs();return path;}
}
}
